{"content": "// Environment workaround for this sandbox:
// plugins.gradle.org is unreachable here (TLS connections are reset) and the pre-seeded
// Gradle cache is missing gradle-errorprone-plugin-4.3.0.jar. This build never applies
// the errorprone plugin -- the root buildscript classpath entry is vestigial (upstream
// OkHttp removed errorprone entirely), so exclude it from the buildscript classpath to
// let the build resolve offline and reach project compilation/tests.
def excludeUnusedErrorprone = { project ->
  project.buildscript.configurations.configureEach { c ->
    c.withDependencies { deps ->
      deps.removeAll { d ->
        d.group == 'net.ltgt.gradle' && d.name == 'gradle-errorprone-plugin'
      }
    }
    c.exclude group: 'net.ltgt.gradle', module: 'gradle-errorprone-plugin'
  }
}

gradle.projectsLoaded { g ->
  g.allprojects(excludeUnusedErrorprone)
}

gradle.beforeProject { p ->
  excludeUnusedErrorprone(p)
}
