{"content": "// Sandbox environment fixes for the OkHttp workspace (/workspace).
//
// 1. plugins.gradle.org is not reachable from this sandbox (its TLS connections are
//    reset), while repo.maven.apache.org is reachable. The OkHttp root build script
//    lists `net.ltgt.gradle:gradle-errorprone-plugin:4.3.0` on its buildscript
//    classpath but never applies the plugin anywhere, so substitute the artifact that
//    is available from Maven Central so buildscript resolution can succeed.
//
// 2. Some unrelated projects (e.g. :module-tests) need plugin-portal-only plugins
//    (com.github.iherasymenko.jlink, org.gradlex.extra-java-module-info) that are not
//    cached, and they are irrelevant to `:okhttp:*` tasks. Configure on demand so
//    Gradle only configures the projects that are actually needed.
//
// These fixes are scoped to builds launched from /workspace.

def sp = gradle.startParameter
def dirs = [sp.currentDir, sp.projectDir].findAll { it != null }*.********Path
def inWorkspace = dirs.any { it.startsWith('/workspace') }

if (inWorkspace) {
  sp.configureOnDemand = true
}

gradle.beforeProject { project ->
  project.buildscript.configurations.configureEach { configuration ->
    configuration.resolutionStrategy.dependencySubstitution {
      substitute(module('net.ltgt.gradle:gradle-errorprone-plugin'))
        .using(module('net.ltgt.gradle:gradle-errorprone-plugin:0.0.6'))
    }
  }
}
